import {gameSnapshot} from '../../public/game/js/portable.js';
import {rotationCalendar} from '../../public/game/js/rotations.js';import {expansion} from '../../public/game/js/expansion-state.js';
import {startBattle,advanceBattle} from '../../public/game/js/battle.js';import {attachTroops} from '../../public/game/js/camp.js';import {deployedTroops} from '../../public/game/js/logistics.js';import {grant} from '../../public/game/js/item.js';
export const COOP_STAGES=[{stage:1,goal:3000,items:{material_choice:1}},{stage:2,goal:10000,items:{vital_pill:1}},{stage:3,goal:20000,items:{material_choice:1,recruit_order:1}}];
export async function cooperativeReady(env,fail){const rows=await env.DB.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name IN ('cooperative_attempts','cooperative_claims')").all();if(rows.results.length!==2)fail(503,'协作讨伐尚未安装：请先执行 0003_cooperative.sql，再使用此功能。');}
export async function cooperativeBoard(env,now,slot){const cal=rotationCalendar(now),totals=await env.DB.prepare('SELECT slot,SUM(damage) AS damage FROM cooperative_attempts WHERE period=? GROUP BY slot ORDER BY damage DESC,slot').bind(cal.period).all(),total=totals.results.reduce((n,v)=>n+v.damage,0);const board={period:cal.period,day:cal.date,name:'协力清剿 · '+cal.route.name,total,stages:COOP_STAGES,entries:totals.results.map(v=>({id:v.slot,damage:v.damage}))};if(slot){const used=await env.DB.prepare('SELECT COUNT(*) AS n FROM cooperative_attempts WHERE period=? AND slot=? AND day=?').bind(cal.period,slot,cal.date).first(),claims=await env.DB.prepare('SELECT stage FROM cooperative_claims WHERE period=? AND slot=?').bind(cal.period,slot).all();board.id=slot;board.used=used.n;board.mine=totals.results.find(v=>v.slot===slot)?.damage||0;board.claimed=claims.results.map(v=>v.stage);}return board;}
export function simulateCooperative(d,raw,now,seed){const s=gameSnapshot(JSON.parse(raw),d),cal=rotationCalendar(now);if(!s.camp||s.camp.buildings.hall<3||!s.team.length||s.battle||s.scheme||s.event||s.realm?.trek||s.expansion?.run)throw Error('上传聚义厅 3 级、已编队且已结束所有战斗与远征的云档。');s.clock=now;s.lastRegen=now;s.rng=seed;s.battleSkillMode='auto';if(s.expansion)s.expansion.smoke=false;startBattle(s,d,{enemies:cal.route.enemies,scale:4,context:{type:'realm',kind:'cooperative',id:'outlaw',terrain:cal.route.terrain}});attachTroops(s,deployedTroops(s));const maximum=s.battle.enemy.reduce((n,u)=>n+u.maxHp,0);for(let i=0;i<180&&!s.battle.outcome;i++)advanceBattle(s,d,1000);const b=s.battle;return {damage:Math.min(2000,Math.max(0,Math.floor((maximum-b.enemy.reduce((n,u)=>n+u.hp,0))/maximum*2000))),outcome:b.outcome,elapsed:b.elapsed,log:b.log.slice(-6)};}
export async function cooperativeAction({request,env,row,hash,input,action,expected,data,now,seed,fail}){await cooperativeReady(env,fail);const cal=rotationCalendar(now);if(action==='cooperate'){if(!/^[a-zA-Z0-9_-]{12,80}$/.test(input.requestId||''))fail(400,'缺少有效的本次讨伐编号。');const replay=await env.DB.prepare('SELECT * FROM cooperative_attempts WHERE slot=? AND request_id=?').bind(row.id,input.requestId).first();if(replay)return {id:row.id,period:replay.period,damage:replay.damage,outcome:replay.outcome,elapsed:replay.elapsed,replayed:true};if(expected!==row.revision)fail(412,'云档已有更新，请重新读取后讨伐。');if(!row.raw)fail(400,'先上传云档。');const used=await env.DB.prepare('SELECT COUNT(*) AS n FROM cooperative_attempts WHERE period=? AND slot=? AND day=?').bind(cal.period,row.id,cal.date).first();if(used.n>=2)fail(409,'此云档今日已讨伐两次。');let result;try{result=simulateCooperative(data,row.raw,now,seed);}catch(e){fail(400,e.message);}if(rotationCalendar(Date.now()).date!==cal.date)fail(409,'讨伐期间已跨日，请重新读取。');const saved=await env.DB.prepare('INSERT INTO cooperative_attempts(period,slot,day,attempt,request_id,source_revision,damage,outcome,elapsed,created_at) SELECT ?,?,?,?,?,?,?,?,?,? WHERE EXISTS(SELECT 1 FROM slots WHERE id=? AND revision=? AND key_hash=?) ON CONFLICT DO NOTHING RETURNING *').bind(cal.period,row.id,cal.date,used.n+1,input.requestId,row.revision,result.damage,result.outcome,result.elapsed,new Date(now).toISOString(),row.id,expected,hash).first();if(!saved){const replay=await env.DB.prepare('SELECT * FROM cooperative_attempts WHERE slot=? AND request_id=?').bind(row.id,input.requestId).first();if(replay)return {id:row.id,period:replay.period,damage:replay.damage,outcome:replay.outcome,elapsed:replay.elapsed,replayed:true};fail(409,'云档或讨伐次数已有更新，请刷新后重试。');}return {id:row.id,period:cal.period,...result,replayed:false};}
 if(action!=='coop-claim')fail(400,'未知协作操作。');if(!row.raw)fail(400,'先上传有效进度再领取阶段奖励。');const prize=COOP_STAGES.find(v=>v.stage===input.stage);if(!prize||input.period!==cal.period)fail(400,'请刷新本期阶段。');if(expected!==row.revision)fail(412,'云档已有更新，请先重新读取。');const board=await cooperativeBoard(env,now,row.id);if(board.claimed.includes(prize.stage))fail(409,'本期此阶段已领取。');if(!board.mine||board.total<prize.goal)fail(400,'需要本期作出有效贡献，且全服达到阶段目标。');const s=gameSnapshot(JSON.parse(row.raw),data);expansion(s).coopClaims[cal.period+'_'+prize.stage]=true;grant(s,{items:prize.items},data);s.revision++;const raw=JSON.stringify(gameSnapshot(s,data)),token=crypto.randomUUID(),stamp=new Date(now).toISOString();if(rotationCalendar(Date.now()).period!==cal.period)fail(409,'已换期，请刷新。');const results=await env.DB.batch([env.DB.prepare('INSERT INTO cooperative_claims(period,slot,stage,token,created_at) SELECT ?,?,?,?,? WHERE EXISTS(SELECT 1 FROM slots WHERE id=? AND revision=? AND key_hash=?) ON CONFLICT DO NOTHING').bind(cal.period,row.id,prize.stage,token,stamp,row.id,expected,hash),env.DB.prepare('UPDATE slots SET raw=?,revision=revision+1,updated_at=? WHERE id=? AND revision=? AND key_hash=? AND EXISTS(SELECT 1 FROM cooperative_claims WHERE period=? AND slot=? AND stage=? AND token=?)').bind(raw,stamp,row.id,expected,hash,cal.period,row.id,prize.stage,token)]);if(!results[1].meta.changes)fail(409,'云档或阶段领取记录已有更新，请刷新后查看。');return {id:row.id,cloudRevision:expected+1,period:cal.period,stage:prize.stage,items:prize.items,message:'奖励已写入云档。请下载比较并接续，尚未替换本机。'};}
