export function validateIdle(s,check){const x=s.idleDispatch;if(x===undefined)return;const obj=v=>v&&typeof v==='object'&&!Array.isArray(v),num=(n,max=Number.MAX_SAFE_INTEGER)=>Number.isSafeInteger(n)&&n>=0&&n<=max;check(obj(x)&&!!s.camp&&x.version===1&&Object.keys(x).sort().join(',')==='bank,earned,mission,revision,version'&&num(x.revision)&&num(x.earned),'采集派遣记录');const keys=new Set([...Object.values(IDLE_ROUTES).flatMap(r=>Object.keys(r.items)),...Object.values(GATHERING_REGIONS).map(r=>r.item),...(s.exploration?Object.values(REGION_CONTACTS).map(h=>h+'_token'):[])]);check(obj(x.bank)&&Object.entries(x.bank).every(([id,n])=>keys.has(id)&&num(n,id.endsWith('_token')?2:96)&&n>0),'采集暂存材料');const m=x.mission;if(m!==null){check(obj(m)&&Object.keys(m).sort().join(',')==='carry,hero,lastAt,region'&&Object.hasOwn(IDLE_ROUTES,m.region)&&idleUnlocked(s,m.region)&&num(m.lastAt,s.clock)&&num(m.carry,IDLE_CYCLE-1),'采集地区与时间');check(idleAvailable({...s,idleDispatch:{...x,mission:null}},m.hero),'采集好汉重复任职');const rates=idleRates(m.region,m.hero,s);check(Object.entries(x.bank).every(([id,n])=>(rates[id]&&n<=16*rates[id])||(s.exploration&&id===REGION_CONTACTS[m.region]+'_token'&&n<=2&&n<=s.exploration.contacts[m.region].earned)),'采集产物与地区');}check(Object.values(x.bank).reduce((a,n)=>a+n,0)<=x.earned,'采集累计产出');}
