import {DELVE_EVENTS,delveOption} from './delve-events.js?v=0.82.0';
import {honors,BUILD_FEATS} from './adventure.js?v=0.82.0';
import {PERSONAL} from './expansion-data.js?v=0.82.0';
export const NEW_GEAR=['field_bandage','watchman_blade','thorn_coat'];
export const hasAdventure=s=>!!s.adventure||s.development?.goal?.kind==='personal'&&PERSONAL[s.development.goal.id]?.introduced===6||s.development?.goal?.kind==='gear'&&NEW_GEAR.includes(s.development.goal.id)||s.equipment.some(e=>NEW_GEAR.includes(e.item))||Object.keys(s.expansion?.personal||{}).some(id=>PERSONAL[id]?.introduced===6)||[s.battle,s.lastBattle].some(b=>b?.context.kind==='personal'&&PERSONAL[b.context.id]?.introduced===6);
export function validateAdventure(s,check){const x=s.adventure;if(x===undefined)return;const obj=v=>v&&typeof v==='object'&&!Array.isArray(v),num=(v,a,b)=>Number.isSafeInteger(v)&&v>=a&&v<=b,shape=(v,keys)=>obj(v)&&Object.keys(v).sort().join(',')===keys.split(' ').sort().join(',');check(shape(x,'version run clears badge feats')&&x.version===1&&obj(x.clears)&&obj(x.feats),'探索记录');for(const [k,n]of Object.entries(x.clears))check(/^(mine|marsh|ruins)_[123]$/.test(k)&&num(n,1,10000000)&&(s.specialDungeons?.clears[k]||0)>=n*3,'探索通关次数');for(const [id,r]of Object.entries(x.feats))check(Object.hasOwn(BUILD_FEATS,id)&&shape(r,'count best team')&&num(r.count,1,10000000)&&num(r.best,0,180000)&&Array.isArray(r.team)&&r.team.length>0&&r.team.length<=3&&new Set(r.team).size===r.team.length&&r.team.every(id=>s.heroes[id]?.status==='owned'),'搭配战绩');check(x.badge===null||honors(s).some(h=>h.id===x.badge&&h.done),'荣誉称号');const r=x.run;if(r===null)return;check(shape(r,'id tier stage team hp choices'+(r.events===undefined?'':' events'))&&['mine','marsh','ruins'].includes(r.id)&&num(r.tier,1,3)&&num(r.stage,0,2)&&Array.isArray(r.team)&&JSON.stringify(r.team)===JSON.stringify(s.team)&&r.team.length>0&&obj(r.hp)&&Array.isArray(r.choices)&&r.choices.every(c=>['rest','rescue','cache'].includes(c)),'探索路线');if(r.events!==undefined)check(Array.isArray(r.events)&&r.events.length===2&&new Set(r.events).size===2&&r.events.every(id=>DELVE_EVENTS[id]?.area===r.id),'探索事件');check(!s.scheme&&!s.event&&!s.realm?.trek&&!s.expansion?.run,'探索互斥');const b=s.battle;check(b?b.context.type==='special'&&b.context.id===r.id&&b.context.tier===r.tier&&r.choices.length===r.stage&&b.context.route===(r.stage?delveOption({...r,stage:r.stage},r.choices.at(-1))?.route:undefined):r.stage>0&&r.choices.length===r.stage-1,'探索节点');check(r.stage===0?Object.keys(r.hp).length===0:Object.keys(r.hp).length===r.team.length&&r.team.every(id=>num(r.hp[id],0,10000))&&Object.values(r.hp).some(n=>n>0),'探索气血');}
export function adventurePreserved(a,b){return !a.adventure||!!b.adventure&&(!a.adventure.run?.events||!b.adventure.run||!!b.adventure.run.events)&&Object.entries(a.adventure.clears).every(([k,n])=>(b.adventure.clears[k]||0)>=n)&&Object.entries(a.adventure.feats).every(([k,r])=>(b.adventure.feats[k]?.count||0)>=r.count&&b.adventure.feats[k].best<=r.best);}
