import {CHALLENGES} from './realm-data.js?v=0.82.0';import {deployedTroops} from './logistics.js?v=0.82.0';import {startBattle} from './battle.js?v=0.82.0';import {attachTroops} from './camp.js?v=0.82.0';import {weeklyScore} from './rotations.js?v=0.82.0';import {affairReward} from './affairs.js?v=0.82.0';import {requireRule,hasOwn,count,journal} from './utils.js?v=0.82.0';
export function groupReason(s,group='open'){if(group==='open')return '';if(!hasOwn(CHALLENGES,group))return '无效的挑战分组';if(!s.camp||!s.team.length)return '先建寨并安排队伍';if(group==='solo'&&s.camp.mode!=='solo')return '独行组要求英雄独行';if(group==='small'&&(s.camp.mode!=='army'||deployedTroops(s)<1||deployedTroops(s)>100))return '百人组要求实际随军 1—100 人';if(group==='mortal'&&s.team.some(id=>(s.heroes[id].quality||0)!==0))return '凡品组要求全员凡品';return '';}
export function challengePlan(s,id,tier){const n=deployedTroops(s),food=5+Math.ceil(n/2);let reason=!s.realm?'先开启山河经营':!hasOwn(CHALLENGES,id)?'无效试炼':s.camp.buildings.hall<3?'聚义厅需 3 级':!Number.isInteger(tier)||tier<1||tier>5||tier>(s.realm.records[id]?.tier||0)+1?'须逐层通关':groupReason(s,id)||((s.daily.counters.realm_challenge||0)>=3?'今日已挑战三次':'');if(!reason&&s.player.stamina<10)reason='体力不足';if(!reason&&s.camp.food<food)reason='粮草不足';return {reason,n,food};}
export function challengeStart(s,d,a){const q=challengePlan(s,a.id,a.tier);requireRule(!q.reason,q.reason);s.player.stamina-=10;s.camp.food-=q.food;count(s,'realm_challenge');startBattle(s,d,{enemies:['guard','bandit_chief'],scale:1+a.tier*.7,context:{type:'realm',kind:'challenge',id:a.id,tier:a.tier,terrain:'land'}});attachTroops(s,q.n);}
export function finishChallenge(s,b,d){if(b.outcome!=='victory')return;const id=b.context.id,tier=b.context.tier,hp=Math.floor(b.team.reduce((n,u)=>n+u.hp/u.maxHp,0)/b.team.length*1000),score=weeklyScore(tier,b.elapsed,hp),old=s.realm.records[id];if(!old||score>old.score)s.realm.records[id]={tier,hp,elapsed:b.elapsed,score,at:s.clock,team:b.team.map(u=>u.id)};const flag='realm_challenge_'+id+'_'+tier;if(!s.progress.flags[flag]){s.progress.flags[flag]=true;affairReward(s,{items:{martial_pages:2,spirit_essence:1,...(tier===5?{recruit_order:1}:{})}},d);if(tier===5)s.progress.flags['realm_badge_'+id]=true;}journal(s,'【专项试炼】'+CHALLENGES[id].name+'第 '+tier+' 层得胜，'+score+' 分。重复通关只刷新较佳记录，不重复发首通奖励。');}
export function challengesPanel(s,d,esc,btn){return '<section class="realm-section" id="realm-challenge"><h2>专项试炼与历史最佳</h2><p>固定敌军五层，聚义厅 3 级起挑战；三组合计每日三次。每层体力 10，粮草 5 加随軍人数一半；首胜残页 2、灵蕴 1，第五层另给招贤令 1 和勋章。首胜奖励全存档每组每层仅一次。</p><div class="realm-grid">'+Object.entries(CHALLENGES).map(([id,m])=>{const r=s.realm.records[id];return '<article class="realm-card"><h3>'+m.name+(s.progress.flags['realm_badge_'+id]?' · 已获勋章':'')+'</h3><p>'+m.text+'</p>'+(r?'<p>历史最佳：'+r.tier+' 层 · '+r.score+' 分</p><p class="note">阵容：'+r.team.map(id=>esc(d.by.heroes[id].name)).join('、')+'</p>':'<p>尚未通关</p>')+[1,2,3,4,5].map(tier=>{const q=challengePlan(s,id,tier);return btn('第 '+tier+' 层'+(s.progress.flags['realm_challenge_'+id+'_'+tier]?' · 已首通':''),{type:'challengeStart',id,tier},'secondary',!!q.reason&&q.reason!==groupReason(s,id));}).join('')+'<p class="note">'+esc(groupReason(s,id)?groupReason(s,id)+'；可点击已解锁层数，在出征准备里调整。':'阵容满足分组条件。')+'</p></article>';}).join('')+'</div><p class="note">这里是本机固定试炼。云端分组榜使用当期周本，由服务器独立演算；到存档页面选择组别参赛。</p></section>';}
