import {finishJourney} from './journey.js?v=0.82.0';import {validateJourneyRun} from './journey-save.js?v=0.82.0';
import {startBattle} from './battle.js?v=0.82.0';import {attachTroops} from './camp.js?v=0.82.0';import {deployedTroops,heroCommand} from './logistics.js?v=0.82.0';import {affairReward} from './affairs.js?v=0.82.0';import {requireRule,random,count,journal} from './utils.js?v=0.82.0';
export const NODES={fight:{name:'山路遭遇',text:'与游匪交锋，胜利暂存碎银 100、精铁 2。'},camp:{name:'林间营地',text:'消耗粮草 15，为未退阵英雄恢复 25% 气血。'},trade:{name:'行商货摊',text:'消耗碎银 80，暂存布匹 3、武学残页 2。'},event:{name:'迷路行旅',text:'赠粮 20，暂存碎银 50、武学残页 3。'},boss:{name:'归路敌寨',text:'击败守寨头目，暂存碎银 200、精铁 4。'}};
export function trekGuard(s,a){if(!s.realm?.trek)return;requireRule(['journeyChoice','journeyNode','journeyReturn','trekNode','trekReturn','battleTick','battleSkill','battleSkillMode','battleItem','battleOrder','battleRetreat','finishBattle','refresh','squadCollect','provisionUse'].includes(a.type),'主队仍在远征。先完成路线或从山河页面撤回，再调整人物与经营。');}
function carryLoot(s,d,complete){const t=s.realm.trek,factor=complete?1:.5;affairReward(s,{silver:Math.floor(t.loot.silver*factor),items:Object.fromEntries(Object.entries(t.loot).filter(([k])=>k!=='silver').map(([k,n])=>[k,Math.floor(n*factor)]).filter(([,n])=>n>0))},d);if(complete)count(s,'trek_wins');journal(s,'【远征归寨】'+(complete?'完成五段路线，全部所得已入库。':'提前撤回，带回已暂存所得的一半；体力和粮草不退。')+'好汉回寨休整，阵亡兵员仍需补充。');s.realm.trek=null;}
export function trekAction(s,d,a){requireRule(s.realm,'先开启山河经营。');if(a.type==='trekStart'){requireRule(s.camp.buildings.hall>=3&&!s.realm.trek&&!s.daily.counters.trek_start&&s.team.length,'聚义厅 3 级、有主队且今日未开始远征。');const n=deployedTroops(s),food=20+Math.ceil(n/2);requireRule(s.player.stamina>=20&&s.camp.food>=food,'需要体力 20、粮草 '+food+'。');requireRule(s.camp.mode==='solo'||n>0,'请先募兵或选择独行。');s.player.stamina-=20;s.camp.food-=food;count(s,'trek_start');const alternatives=['camp','trade','event'];s.realm.trek={team:[...s.team],node:0,route:Array.from({length:5},(_,i)=>i===4?['boss']:['fight',alternatives[Math.floor(random(s)*3)]]),hp:Object.fromEntries(s.team.map(id=>[id,10000])),loot:{silver:0,iron:0,cloth:0,martial_pages:0}};journal(s,'【远征启程】五段路线已展开。气血与兵力连续结算，可随时在节点间撤回。');return;}
 const t=s.realm.trek;requireRule(t,'当前没有短程远征。');requireRule(!t.journey,'请从江湖游历页面继续或收队。');if(a.type==='trekReturn'){carryLoot(s,d,t.node===5);return;}requireRule(a.type==='trekNode'&&t.node<5&&t.route[t.node].includes(a.kind),'请选择当前节点显示的路线。');if(a.kind==='fight'||a.kind==='boss'){requireRule(Object.values(t.hp).some(v=>v>0),'全队已退阵，请撤回。');const n=Math.min(deployedTroops(s),t.team.filter(id=>t.hp[id]>0).reduce((n,id)=>n+heroCommand(s,id),0)),food=5+Math.ceil(n/5);requireRule(s.camp.food>=food,'本段战斗需粮草 '+food+'。');requireRule(s.camp.mode==='solo'||n>0,'已无可出战士兵，请撤回补员。');s.camp.food-=food;startBattle(s,d,{enemies:a.kind==='boss'?['guard','bandit_chief']:['bandit','road_raider'],scale:a.kind==='boss'?2.2:1.1+t.node*.2,context:{type:'realm',kind:'trek',id:'trail',tier:t.node+1,terrain:'forest'}});attachTroops(s,n);for(const u of s.battle.team)u.hp=t.hp[u.id]?Math.max(1,Math.floor(u.maxHp*t.hp[u.id]/10000)):0;return;}
 if(a.kind==='camp'){requireRule(s.camp.food>=15,'休整需要粮草 15。');s.camp.food-=15;for(const id of t.team)if(t.hp[id]>0)t.hp[id]=Math.min(10000,t.hp[id]+2500);}if(a.kind==='trade'){requireRule(s.player.silver>=80,'交易需要碎银 80。');s.player.silver-=80;t.loot.cloth+=3;t.loot.martial_pages+=2;}if(a.kind==='event'){requireRule(s.camp.food>=20,'赠粮需要 20。');s.camp.food-=20;t.loot.silver+=50;t.loot.martial_pages+=3;}t.node++;journal(s,'【远征节点】'+NODES[a.kind].name+'已处理，所得暂存至回寨。');}
export function finishTrek(s,b,d){if(s.realm?.trek?.journey){finishJourney(s,b,d);return;}if(b.context.type!=='realm'||b.context.kind!=='trek')return;const t=s.realm?.trek;requireRule(t&&b.context.tier===t.node+1,'远征节点不匹配。');for(const u of b.team)t.hp[u.id]=Math.floor(u.hp/u.maxHp*10000);if(b.outcome!=='victory'){carryLoot(s,d,false);return;}t.loot.silver+=t.node===4?200:100;t.loot.iron+=t.node===4?4:2;if(s.realm.equipped==='compass')for(const id of t.team)if(t.hp[id])t.hp[id]=Math.min(10000,t.hp[id]+500);t.node++;journal(s,'【远征得胜】气血和兵损保留，战利品暂存。'+(t.node===5?'归路已通，可整队回寨。':'可继续选择下一段路线。'));}
export function validateTrek(s,check){const t=s.realm?.trek;if(t===undefined||t===null)return;if(t.journey){validateJourneyRun(s,check);return;}const num=(n,max)=>Number.isSafeInteger(n)&&n>=0&&n<=max;check(t&&Array.isArray(t.team)&&t.team.length>0&&t.team.length<=3&&JSON.stringify(t.team)===JSON.stringify(s.team)&&num(t.node,5)&&Array.isArray(t.route)&&t.route.length===5,'远征队伍与路线');check(t.packs===undefined||num(t.packs,2),'远征药包');check(t.hp&&Object.keys(t.hp).length===t.team.length&&t.team.every(id=>num(t.hp[id],10000)),'远征气血');for(let i=0;i<5;i++)check(Array.isArray(t.route[i])&&(i===4?t.route[i].length===1&&t.route[i][0]==='boss':t.route[i].length===2&&t.route[i][0]==='fight'&&['camp','trade','event'].includes(t.route[i][1])),'远征节点');check(t.loot&&Object.keys(t.loot).length===4&&['silver','iron','cloth','martial_pages'].every(k=>num(t.loot[k],1000)),'远征暂存所得');if(s.battle?.context.kind==='trek')check(s.battle.context.tier===t.node+1&&t.node<5,'远征交战次序');}
export function trekPanel(s,d,btn){const t=s.realm.trek;if(!t)return '<section class="realm-section" id="realm-trek"><h2>短程远征 · 五段山路</h2><p>每日一次，聚义厅 3 级开放。出发消耗体力 20、粮草 '+(20+Math.ceil(deployedTroops(s)/2))+'；战斗节点另需粮草 5 加实际兵力五分之一向上取整。途中保持气血与兵损，退阵好汉本次远征不再统兵，五段路线在启程后全部可见。</p>'+btn('开始短程远征',{type:'trekStart'},'primary',s.camp.buildings.hall<3||!!s.daily.counters.trek_start||!s.team.length)+'</section>';return '<section class="realm-section" id="realm-trek"><h2>远征途中 · 已走 '+t.node+' / 5 段</h2><p>'+t.team.map(id=>d.by.heroes[id].name+'气血 '+(t.hp[id]/100).toFixed(1)+'%').join(' · ')+'</p><p>暂存：碎银 '+t.loot.silver+'、精铁 '+t.loot.iron+'、布匹 '+t.loot.cloth+'、残页 '+t.loot.martial_pages+'</p><div class="realm-route">'+t.route.map((options,i)=>'<div class="'+(i===t.node?'current':'')+'"><b>第 '+(i+1)+' 段'+(i<t.node?' · 已走':'')+'</b>'+options.map(kind=>'<p>'+NODES[kind].name+'</p>').join('')+'</div>').join('')+'</div>'+(t.node<5?t.route[t.node].map(kind=>'<p>'+NODES[kind].text+'</p>'+btn('选择'+NODES[kind].name,{type:'trekNode',kind},'secondary')).join(''):'<p>五段路线已走完，点击回寨领取全部所得。</p>')+btn('野营药包 ×'+(s.inventory.camp_pack||0)+' · 恢复 20%',{type:'provisionUse',id:'camp_pack'},'secondary',!s.inventory.camp_pack||(t.packs||0)>=2||!Object.values(t.hp).some(v=>v>0&&v<10000))+btn(t.node===5?'整队回寨 · 领取全部所得':'提前撤回 · 带走暂存所得一半',{type:'trekReturn'},'primary')+'</section>';}
