export const SIXTH_MISSIONS={v6_outer:{level:30,hall:4,scale:4.5,terrain:'land',stamina:12},v6_cut:{level:31,hall:4,scale:4.8,terrain:'land',stamina:12},v6_rescue:{level:32,hall:4,scale:5.2,terrain:'land',stamina:14},v6_final:{level:34,hall:4,scale:5.8,terrain:'land',stamina:18}};
export const sixthEnemyList=(s,id,enemies)=>id==='v6_final'&&s.progress.flags.v6_aid_cut?enemies.filter(e=>e!=='v6_rider'):enemies;
export function applySixthPreparation(s,b){if(b.context.id!=='v6_final')return;if(s.progress.flags.v6_smoke_known){for(const u of b.enemy)u.attack=Math.round(u.attack*.85);b.log.push('【高唐准备】辨明烟阵，敌军攻击降低 15%。');}if(s.progress.flags.v6_aid_cut)b.log.push('【高唐准备】截断援道，敌方援骑无法入场。');}
export const hasSixthVolume=s=>!!s.progress.flags.volume_six_complete||Object.keys(s.progress.flags).some(id=>id.startsWith('v6_')&&s.progress.flags[id])||s.progress.visited.some(id=>id.startsWith('v6_'))||Object.keys(s.progress.stories).some(id=>id.startsWith('v6_'))||s.battle?.context.id?.startsWith('v6_')||s.lastBattle?.context.id?.startsWith('v6_');
