import {JOURNEYS} from './journey-data.js?v=0.82.0';import {validateJourneyRecord} from './journey-save.js?v=0.82.0';
import {PERSONAL} from './expansion-data.js?v=0.82.0';
import {finishChallenge} from './challenges.js?v=0.82.0';
import {weeklyScore} from './rotations.js?v=0.82.0';
import {finishTrek,validateTrek} from './trek.js?v=0.82.0';
import {TALENTS} from './talents.js?v=0.82.0';
import {validateSquad} from './squads.js?v=0.82.0';
import { REGIONS, FACTIONS, CONTRACTS, BRANCHES, RELICS, CHALLENGES } from './realm-data.js?v=0.82.0';
import { deployedTroops } from './logistics.js?v=0.82.0';
import { startBattle } from './battle.js?v=0.82.0';
import { attachTroops } from './camp.js?v=0.82.0';
import { affairReward } from './affairs.js?v=0.82.0';
import { requireRule, hasOwn, count, journal } from './utils.js?v=0.82.0';
export function realmOpen(s){requireRule(s.camp&&!s.realm,'先建寨；已开启的山河经营不必重开。');s.realm={version:1,regions:Object.fromEntries(Object.keys(REGIONS).map(id=>[id,{security:40,supply:40,pact:false}])),relations:{merchants:0,villages:0,river:0},branches:{},armyXp:0,relics:[],equipped:null,squad:null,trek:null,records:{}};journal(s,'【山河经营】三路商情已展开。治安与补给随主动处理事务改变，离线不会自动衰退。');}
export function realmPlan(s,id,kind){const m=REGIONS[id],a=CONTRACTS[kind],r=s.realm?.regions[id];let reason=!r?'先开启山河经营':!a?'无效的委托':s.camp.buildings.hall<m.hall?'聚义厅需要 '+m.hall+' 级':!s.team.length?'先安排主队':s.daily.counters['realm_'+id]?'今日此地区已受理一件委托':kind==='commission'&&s.realm.relations[m.faction]<20?'对应势力关系达到 20 后开放':'';const troops=deployedTroops(s),food=Math.ceil(troops/2)+5;
 if(!reason&&s.player.stamina<a.stamina)reason='体力不足';if(!reason&&s.camp.food<food)reason='出征粮草不足';if(!reason&&s.camp.mode==='army'&&!troops)reason='先募兵或改为独行';return {reason,troops,food,stamina:a?.stamina||0,scale:(m?.scale||1)*(kind==='commission'?1.3:1)};}
export function startRealmBattle(s,d,a){const q=realmPlan(s,a.id,a.kind);requireRule(!q.reason,q.reason);s.player.stamina-=q.stamina;s.camp.food-=q.food;count(s,'realm_'+a.id);const m=REGIONS[a.id];startBattle(s,d,{enemies:m.enemy,scale:q.scale,context:{type:'realm',id:a.id,kind:a.kind,period:s.daily.date,terrain:m.terrain}});attachTroops(s,q.troops);}
export function finishRealmBattle(s,b,d){if(b.context.type!=='realm')return;if(b.context.kind==='challenge'){finishChallenge(s,b,d);return;}if(b.context.kind==='trek'){finishTrek(s,b,d);return;}const m=REGIONS[b.context.id],a=CONTRACTS[b.context.kind];if(!m||!a)return;const r=s.realm.regions[b.context.id];if(b.outcome==='victory'){r.security=Math.min(100,r.security+a.security);r.supply=Math.min(100,r.supply+a.supply);s.realm.relations[m.faction]=Math.min(100,s.realm.relations[m.faction]+a.relation);affairReward(s,a.reward,d);count(s,'realm_win_'+b.context.kind);journal(s,'【商路转安】'+m.name+'：治安 +'+a.security+'、补给 +'+a.supply+'，'+FACTIONS[m.faction]+'关系 +'+a.relation+'。');}else{r.security=Math.max(0,r.security-3);journal(s,'【商路受挫】'+m.name+'治安 −3；已出发的粮草与次数不返还。');}}
export function realmAction(s,d,a){if(a.type==='realmOpen'){realmOpen(s);return;}requireRule(s.realm,'先开启山河经营。');if(a.type==='realmBattle'){startRealmBattle(s,d,a);return;}const m=REGIONS[a.id],r=s.realm.regions[a.id];requireRule(m&&r,'没有此地区。');if(a.type==='realmTrade'){requireRule(!s.daily.counters['realm_trade_'+a.id],'今日已经交易。');requireRule(s.camp.buildings.hall>=m.hall,'寨子规模不足。');const cost=r.pact?120:s.realm.relations[m.faction]>=20?150:180;requireRule(s.player.silver>=cost,'碎银不足。');s.player.silver-=cost;const food=40+Math.floor(r.supply/2);s.camp.food=Math.min(10000000,s.camp.food+food);count(s,'realm_trade_'+a.id);journal(s,'【商路互市】碎银 −'+cost+'，粮草 +'+food+'；当地补给决定货量，关系决定价格。');return;}
 if(a.type==='realmPact'){requireRule(!r.pact&&r.security>=80&&s.realm.relations[m.faction]>=30,'治安 80、关系 30 后可缔结商盟，每处一次。');requireRule(s.player.silver>=300,'缔约需要碎银 300。');s.player.silver-=300;r.pact=true;affairReward(s,{items:{recruit_order:1}},d);journal(s,'【缔结商盟】'+FACTIONS[m.faction]+'与山寨长期互助；本地互市优惠已生效，获得招贤令 1。');return;}throw Error('未知山河经营指令。');}
export function validRealmContext(c){if(c?.type==='realm'&&c.kind==='trek'&&c.id?.startsWith('journey_')){const id=c.id.slice(8);return hasOwn(JOURNEYS,id)&&Number.isInteger(c.tier)&&c.tier>=1&&c.tier<=5&&c.terrain===JOURNEYS[id].terrain;}if(c?.type==='realm'&&['personal','defense','relay'].includes(c.kind))return c.kind==='personal'?hasOwn(PERSONAL,c.id)&&c.tier===1&&c.terrain===PERSONAL[c.id].terrain:c.id==='venture'&&Number.isInteger(c.tier)&&c.tier>=1&&c.tier<=3&&c.terrain===(c.kind==='relay'&&c.tier===2?'water':'land');return c?.type==='realm'&&c.kind==='challenge'?hasOwn(CHALLENGES,c.id)&&Number.isInteger(c.tier)&&c.tier>=1&&c.tier<=5&&c.terrain==='land':c?.type==='realm'&&c.kind==='trek'?c.id==='trail'&&Number.isInteger(c.tier)&&c.tier>=1&&c.tier<=5&&c.terrain==='forest':c?.type==='realm'&&hasOwn(REGIONS,c.id)&&hasOwn(CONTRACTS,c.kind)&&/^\d{4}-\d{2}-\d{2}$/.test(c.period)&&c.terrain===REGIONS[c.id].terrain;}
export function validateRealm(s,d,check){if(s.realm===undefined){check(s.battle?.context.type!=='realm'&&s.battle?.realm===undefined,'山河战局');return;}const r=s.realm,obj=x=>x&&typeof x==='object'&&!Array.isArray(x),num=(v,max=10000000)=>Number.isSafeInteger(v)&&v>=0&&v<=max;check(s.camp&&obj(r)&&r.version===1&&obj(r.regions)&&Object.keys(r.regions).length===3&&obj(r.relations)&&Object.keys(r.relations).length===3,'山河经营');for(const id of Object.keys(REGIONS)){const p=r.regions[id];check(obj(p)&&num(p.security,100)&&num(p.supply,100)&&typeof p.pact==='boolean','地区状况');}for(const id of Object.keys(FACTIONS))check(num(r.relations[id],100),'势力关系');check(obj(r.branches)&&num(r.armyXp,(s.camp.troops+s.camp.wounded)*200)&&Array.isArray(r.relics)&&obj(r.records),'山河扩展');check(r.relics.length<=3&&new Set(r.relics).size===r.relics.length&&r.relics.every(id=>hasOwn(RELICS,id))&&(r.equipped===null||r.relics.includes(r.equipped)),'军中藏品');for(const [id,v]of Object.entries(r.records))check(hasOwn(CHALLENGES,id)&&obj(v)&&num(v.tier,5)&&v.tier>=1&&num(v.hp,1000)&&num(v.elapsed,180000)&&v.score===weeklyScore(v.tier,v.elapsed,v.hp)&&num(v.at,s.clock)&&Array.isArray(v.team)&&v.team.length>=1&&v.team.length<=3&&new Set(v.team).size===v.team.length&&v.team.every(id=>s.heroes[id]?.status==='owned'),'专项试炼记录');if(r.relicClaims!==undefined){check(obj(r.relicClaims),'藏品领取记录');for(const [id,n]of Object.entries(r.relicClaims))check(hasOwn(RELICS,id)&&num(n),'藏品领取次数');}for(const [id,value]of Object.entries(r.branches))check(hasOwn(BRANCHES,id)&&hasOwn(BRANCHES[id].options,value)&&s.camp.buildings[id]>=2,'设施分支');if(r.paths!==undefined){check(obj(r.paths),'人物战法');for(const [id,path]of Object.entries(r.paths))check(hasOwn(TALENTS,id)&&s.heroes[id]?.status==='owned'&&(s.heroes[id].quality||0)>=1&&['assault','guard'].includes(path),'人物战法选择');}if(s.battle?.realm){const b=s.battle,x=b.realm;check(x.version===1&&(x.relic===null||hasOwn(RELICS,x.relic))&&[1,.9].includes(x.medical)&&[0,.025,.05,.1].includes(x.veteran)&&obj(x.paths)&&obj(x.qualities),'山河战斗规则');for(const id of Object.keys(x.paths))check(b.team.some(u=>u.id===id)&&['assault','guard'].includes(x.paths[id]),'战中人物战法');for(const [id,q]of Object.entries(x.qualities))check(b.team.some(u=>u.id===id)&&num(q,2),'战中品质');}validateJourneyRecord(s,check);validateSquad(s,check);validateTrek(s,check);if(s.battle?.context.type==='realm')check(validRealmContext(s.battle.context),'山河战斗来源');}
