export const SEVENTH_MISSIONS={v7_probe:{level:35,hall:4,scale:5.4,terrain:'water',stamina:12},v7_cut:{level:36,hall:4,scale:5.6,terrain:'land',stamina:12},v7_break:{level:36,hall:4,scale:5.8,terrain:'land',stamina:14},v7_final:{level:38,hall:4,scale:6.2,terrain:'land',stamina:18}};
export const seventhEnemyList=(s,id,enemies)=>id==='v7_final'&&s.progress.flags.v7_aid_cut?enemies.filter(e=>e!=='v7_archer'):enemies;
export function applySeventhPreparation(s,b){if(!['v7_break','v7_final'].includes(b.context.id))return;if(s.progress.flags.v7_hook){for(const u of b.enemy)u.defense=Math.round(u.defense*.75);b.log.push('【钩镰破骑】钩镰撬开马甲，敌军防御降低25%。');}else if(s.progress.flags.v7_trench){for(const u of b.enemy){u.attack=Math.round(u.attack*.8);u.speed=Math.round(u.speed*.85);u.nextAttackAt=Math.round(Math.max(900,Math.min(3000,300000/(100+u.speed))));}b.log.push('【壕沟阻骑】骑队无法齐冲，敌军攻击降低20%、速度降低15%。');}if(b.context.id==='v7_final'&&s.progress.flags.v7_aid_cut)b.log.push('【北路截援】弓手未能赶到，敌军少一队弓手。');}
export const hasSeventhVolume=s=>!!(s.location?.startsWith('v7_')||s.progress.flags.volume_seven_complete||Object.keys(s.progress.flags).some(id=>id.startsWith('v7_')&&s.progress.flags[id])||s.progress.visited.some(id=>id.startsWith('v7_'))||Object.keys(s.progress.stories).some(id=>id.startsWith('v7_'))||s.battle?.context.id?.startsWith('v7_')||s.lastBattle?.context.id?.startsWith('v7_'));
