const condition={healthy:'自身气血高于 70% 时伤害',high:'目标气血高于 70% 时伤害',low:'目标气血低于 40% 时伤害',normal:'普攻伤害',magic:'谋攻伤害',long:'交战 15 秒后伤害',early:'开战前 12 秒伤害',boss:'对首领伤害',army:'实际带兵时伤害',hurt:'自身气血低于 50% 时伤害',alone:'独行时伤害',control:'对眩晕敌人伤害',armor:'对破甲敌人伤害',water:'水域伤害',mountain:'山地伤害'};
export const TALENTS=Object.fromEntries(rows.map(([id,name,kind,value,opening,middle])=>[id,{name,kind,value,opening,middle,text:kind==='rally'?'开场全队怒气 +'+value+'。':kind==='guard'?'开场自身防御 +'+Math.round(value*100)+'%。':kind==='haste'?'自身首次普攻提前 '+value+' 毫秒。':condition[kind]+' +'+Math.round(value*100)+'%。'}]));
export const EXTRA_CHRONICLES=Object.fromEntries(rows.map(([id,name,kind,value,opening,middle])=>[id,{title:name,opening:opening+'。',middle:middle+'。',ending:'伙伴将这段经历记入梁山志，'+name+'的心得留给后来入寨的人。',task:'本人参与胜利 3 次，聚义厅达到 2 级',test:s=>(s.stats['hero_wins_'+id]||0)>=3&&s.camp?.buildings.hall>=2,materials:{martial_pages:3,iron:2}}]));
export function talentCondition(b,u,t,normal,strategy){const k=TALENTS[u.id]?.kind;return k==='healthy'?u.hp>u.maxHp*.7:k==='high'?t.hp>t.maxHp*.7:k==='low'?t.hp<t.maxHp*.4:k==='normal'?normal:k==='magic'?strategy:k==='long'?b.elapsed>=15000:k==='early'?b.elapsed<12000:k==='boss'?!!t.boss:k==='army'?!!u.corps?.troops:k==='hurt'?u.hp<u.maxHp*.5:k==='alone'?!b.expedition?.troops:k==='control'?t.statuses.some(v=>v.id==='stun'):k==='armor'?t.statuses.some(v=>v.id==='armor_break'):k==='water'?b.depth?.terrain==='water':k==='mountain'?b.depth?.terrain==='mountain':false;}
export function talentFactor(b,u,t,{normal=false,strategy=false}={}){if(!b.realm||u.side!=='team')return 1;const m=TALENTS[u.id];let n=m&&talentCondition(b,u,t,normal,strategy)?1+m.value:1;const path=b.realm.paths[u.id],quality=b.realm.qualities[u.id]||0;if(path==='assault')n*=1+(quality===2?.08:.04);if(path==='guard')n*=.96;return n;}
export function chooseHeroPath(s,a){requireRule(s.realm&&hasOwn(TALENTS,a.id)&&s.heroes[a.id]?.status==='owned'&&(s.heroes[a.id].quality||0)>=1,'已入寨的天罡好汉达到灵品后可选择战法。');requireRule(['assault','guard'].includes(a.choice),'请选择破锋或守成。');requireRule(s.realm.paths?.[a.id]!==a.choice,'已经采用此战法。');requireRule(s.player.silver>=200&&(s.inventory.martial_pages||0)>=3,'调整战法需要碎银 200、武学残页 3。');s.player.silver-=200;s.inventory.martial_pages-=3;s.realm.paths??={};s.realm.paths[a.id]=a.choice;journal(s,'【人物战法】已改为'+(a.choice==='assault'?'破锋':'守成')+'，后续新战局生效。');}
export function talentPanel(s,d,h,btn){const m=TALENTS[h.id];if(!m)return '';const owned=s.heroes[h.id]?.status==='owned',quality=s.heroes[h.id]?.quality||0,path=s.realm?.paths?.[h.id];return '<section class="realm-section"><h3>天罡本领 · '+m.name+'</h3><p>'+m.text+'</p><p class="note">开启山河经营后，新战局生效；凡品可用基础本领。灵品可选择破锋（伤害 +4%、防御 −4%）或守成（防御 +8%、伤害 −4%）；仙品强化为破锋伤害 +8% 或守成防御 +14%，相应代价仍保留。两者互斥。</p><p>当前：'+(path==='assault'?'破锋':path==='guard'?'守成':'未选升品战法')+'</p>'+['assault','guard'].map(choice=>btn(choice==='assault'?'选择破锋':'选择守成',{type:'heroPath',id:h.id,choice},'secondary',!owned||!s.realm||quality<1||path===choice||s.player.silver<200||(s.inventory.martial_pages||0)<3)).join('')+'<p class="note">每次调整消耗碎银 200、武学残页 3；已经开始的交战不变。</p></section>';}
