import {BRANCHES} from './realm-data.js?v=0.82.0';import {requireRule,hasOwn,journal} from './utils.js?v=0.82.0';export const recruitPrice=s=>s.realm?.branches.barracks==='recruits'?2:3;
export function productionBonus(s,id){const b=s.realm?.branches.farm;return b==='steady'?(id==='farm'?2:id==='workshop'?-1:0):b==='surplus'?(id==='farm'?4:id==='lumber'?-2:0):0;}
export function buildingBranch(s,a){requireRule(s.realm&&hasOwn(BRANCHES,a.id)&&hasOwn(BRANCHES[a.id].options,a.choice),'请选择有效的设施分支。');requireRule(s.camp.buildings[a.id]>=2,'对应设施达到 2 级后可分支改造。');requireRule(s.realm.branches[a.id]!==a.choice,'已经采用此分支。');requireRule(s.player.silver>=300&&s.camp.wood>=40,'改造需要碎银 300、木材 40。');s.player.silver-=300;s.camp.wood-=40;s.realm.branches[a.id]=a.choice;journal(s,'【设施改造】'+BRANCHES[a.id].name+'采用'+BRANCHES[a.id].options[a.choice].name+'。只影响之后的生产与新出征。');}
export function buildingsPanel(s,btn){return '<section class="realm-section" id="realm-build"><h2>设施分支 · 建寨布局</h2><p>对应建筑 2 级后可改造；每次调整碎银 300、木材 40。不重算已产物资与已出发战局。</p><div class="realm-grid">'+Object.entries(BRANCHES).map(([id,m])=>'<article class="realm-card"><h3>'+m.name+' · '+s.camp.buildings[id]+' 级</h3>'+Object.entries(m.options).map(([choice,v])=>'<p><b>'+v.name+'</b>：'+v.text+'</p>'+btn(s.realm.branches[id]===choice?'已采用':v.name,{type:'buildingBranch',id,choice},'secondary',s.realm.branches[id]===choice||s.camp.buildings[id]<2||s.player.silver<300||s.camp.wood<40)).join('')+'</article>').join('')+'</div></section>';}
