import {newEquipment,gainItem} from './item.js?v=0.82.0';
import {requireRule,journal,hasOwn} from './utils.js?v=0.82.0';
export const ROUTE_PRIZES={forest:{name:'青石路契',equipment:'route_forest_blade',title:'截令短刃',text:'攻击 +32、速度 +8；开战时敌方首位攻击降低 15%，持续 6 秒。适合抢先压制。'},water:{name:'芦荡路契',equipment:'route_water_charm',title:'渡潮佩',text:'谋略 +24、气血 +100；穿戴者开战怒气 +20。适合尽早施展治疗或打断。'},mountain:{name:'断崖路契',equipment:'route_mountain_armor',title:'守隘甲',text:'防御 +25、气血 +180；穿戴者开战获得 15% 护阵，持续 8 秒。适合前排承伤。'}};
export const ROUTE_PRICE=6;
export const routeBalance=(s,id)=>(s.realm?.journey?.rewards?.earned[id]||0)-(s.realm?.journey?.rewards?.spent[id]||0);
export function openRouteRewards(s){return s.realm.journey.rewards??={version:1,target:'forest',earned:{},spent:{}};}
export function awardRouteMarks(s,region,tier){const r=openRouteRewards(s);requireRule((r.earned[region]||0)+tier+1<=10000000,'路契累计已达上限。');r.earned[region]=(r.earned[region]||0)+tier+1;journal(s,'【路线积累】'+ROUTE_PRIZES[region].name+' +'+(tier+1)+'；现有 '+routeBalance(s,region)+'，专属装备需 '+ROUTE_PRICE+'。');}
export function routeRewardAction(s,d,a){requireRule(hasOwn(ROUTE_PRIZES,a.region),'请选择有效路线。');requireRule(!s.realm?.trek&&!s.expansion?.run,'先完成正在进行的远征。');const r=openRouteRewards(s),m=ROUTE_PRIZES[a.region];if(a.type==='journeyTarget'){r.target=a.region;journal(s,'【下趟目标】追踪'+m.title+'，从对应路线积累路契。');return;}
 requireRule(a.type==='journeyExchange'&&['gear','supplies'].includes(a.choice),'请选择装备或行路补给。');const cost=a.choice==='gear'?ROUTE_PRICE:2;requireRule(routeBalance(s,a.region)>=cost,m.name+'不足，还差 '+(cost-routeBalance(s,a.region))+'。');
 if(a.choice==='gear'){requireRule(s.equipment.length<200,'装备已达 200 件，请先整理。');const e=newEquipment(s,m.equipment);e.locked=true;s.commandVersion=1;}else {requireRule((s.inventory.herb||0)+3<=10000000&&(s.inventory.iron||0)+2<=10000000,'材料数量已达上限。');gainItem(s,'herb',3,d);gainItem(s,'iron',2,d);}
 r.spent[a.region]=(r.spent[a.region]||0)+cost;if(a.choice==='gear')r.target=Object.keys(ROUTE_PRIZES).find(id=>!s.equipment.some(e=>e.item===ROUTE_PRIZES[id].equipment))||a.region;journal(s,'【路契兑换】'+m.name+' −'+cost+'，获得'+(a.choice==='gear'?m.title+'（已锁定，可到行囊穿戴）':'草药 3、精铁 2')+'。');
}
export function validateRouteRewards(s,check){const r=s.realm?.journey?.rewards;if(r===undefined)return;const obj=x=>x&&typeof x==='object'&&!Array.isArray(x),num=n=>Number.isSafeInteger(n)&&n>=0&&n<=10000000;check(obj(r)&&r.version===1&&hasOwn(ROUTE_PRIZES,r.target)&&obj(r.earned)&&obj(r.spent),'路线奖励记录');for(const field of ['earned','spent'])check(Object.entries(r[field]).every(([id,n])=>hasOwn(ROUTE_PRIZES,id)&&num(n)),'路契账目');for(const id of Object.keys(ROUTE_PRIZES))check((r.spent[id]||0)<=(r.earned[id]||0)&&(!(r.earned[id]>0)||s.realm.journey.best[id]>=1),'路契余额与通路');}
// Opening effects use existing saved rage/status fields; never reapply on reload.
export function routeEquipmentOpening(s,b){if(b.guest)return;for(const u of b.team){if(b.context.type==='realm'&&(b.context.kind==='trek'&&s.realm?.trek?.hp[u.id]===0||b.context.kind==='defense'&&s.expansion?.run?.hp[u.id]===0))continue;const gear=s.equipment.filter(e=>e.hero===u.id).map(e=>e.item);if(gear.includes('route_water_charm')){u.rage=Math.min(100,u.rage+20);b.log.push('【渡潮佩】'+u.name+'开战怒气 +20。');}for(const [id,target,status,value,ms] of [['route_forest_blade',b.enemy[0],'weaken',.15,6000],['route_mountain_armor',u,'guard',.15,8000]])if(gear.includes(id)&&target){const old=target.statuses.find(x=>x.id===status);if(old){old.value=Math.max(old.value,value);old.expiresAt=Math.max(old.expiresAt,ms);}else target.statuses.push({id:status,value,expiresAt:ms});b.log.push('【路线装备】'+u.name+(status==='weaken'?'压低敌首位攻击，持续 6 秒。':'获得 15% 护阵，持续 8 秒。'));}}}
