import {LESSONS,lessonPassed,validLessonContext} from './lessons-data.js?v=0.82.0';
import {startBattle} from './battle.js?v=0.82.0';
import {requireRule,journal} from './utils.js?v=0.82.0';
export function lessonStart(s,d,id){requireRule(s.camp&&Object.hasOwn(LESSONS,id),'建寨后可选择演武课程。');requireRule(!s.realm?.trek&&!s.expansion?.run,'先完成当前远征。');const m=LESSONS[id];s.lessons??={version:1,completed:[]};startBattle(s,d,{enemies:[m.enemy],guest:{id:m.hero,level:8},context:{type:'lesson',id}});const b=s.battle;b.lesson={version:1,guarded:0};const u=b.team[0],e=b.enemy[0];u.rage=100;if(id==='heal')u.hp=Math.floor(u.maxHp*.45);e.hp=e.maxHp=12000;e.attack=140;e.defense=20;e.skills=[];e.nextAttackAt=8000;if(e.boss)e.boss.readyAt=2000;b.log.push('【演武】只借用教习阵容，不消耗体力、粮草或药物，不改变自己的好汉、装备和出阵配置。完成目标即可结束，不必击倒教习。');journal(s,'【演武开始】'+m.name+'：'+m.tip);}
export function finishLesson(s,b){const passed=lessonPassed(b)&&b.outcome==='victory',m=LESSONS[b.context.id];if(passed&&!s.lessons.completed.includes(b.context.id))s.lessons.completed.push(b.context.id);journal(s,'【演武'+(passed?'完成':'收队')+'】'+m.name+'。'+(passed?'操作已掌握，可以回到真实出征试用。':'本次未完成操作，随时可重试，不扣物资。'));s.battle=null;}
export function validateLessons(s,check){const r=s.lessons;if(r!==undefined)check(r&&r.version===1&&Array.isArray(r.completed)&&new Set(r.completed).size===r.completed.length&&r.completed.every(id=>Object.hasOwn(LESSONS,id)),'演武进度');const b=s.battle;if(b?.context.type==='lesson'){const m=LESSONS[b.context.id];check(validLessonContext(b.context)&&r&&s.camp&&b.guest&&b.rules===2&&!b.expedition&&!b.journey&&!b.expansion&&!b.realm&&!b.martial&&b.team.length===1&&b.team[0].id===m.hero&&b.enemy.length===1&&b.enemy[0].model===m.enemy,'演武阵容');check(b.lesson?.version===1&&Number.isSafeInteger(b.lesson.guarded)&&b.lesson.guarded>=0&&b.lesson.guarded<=1000,'演武实操记录');check(b.outcome!=='victory'||lessonPassed(b),'演武目标未完成');}else check(!b?.lesson,'演武记录与来源');}
