import {REPLAY_CHALLENGES,challengeKey,replayChallengeResult} from './replay-challenges.js?v=0.82.0';
import {startBattle,makeEnemyUnits} from './battle.js?v=0.82.0';
import {attachTroops} from './camp.js?v=0.82.0';
import {initializeLateBattle} from './late-mainline-combat.js?v=0.82.0';
import {lateMissionPlan} from './late-mainline-data.js?v=0.82.0';
import {replayMissions,replayUnlocked,replayId,replayKey,REPLAY_DIFFICULTIES} from './replays-data.js?v=0.82.0';
import {requireRule,journal} from './utils.js?v=0.82.0';
export function replayReason(s,id,tier,challenge){return challenge!==undefined&&(!Object.hasOwn(REPLAY_CHALLENGES,challenge)||tier!==2)?'请选择实战难度的挑战条件。':challenge!==undefined&&!s.progress.flags.volume_twelve_complete?'十二卷完结后开放挑战条件。':challenge==='pair'&&s.team.length>2?'双人破阵最多安排两名好汉。':challenge!==undefined&&(s.replays?.challenges?.[challengeKey(id,tier,challenge)]?.count||0)>=10000000?'已达挑战记录上限。': !replayUnlocked(s,id)?'完成这段主线后可回顾；终卷通关后开放另外两条结局路线。':![1,2].includes(tier)?'请选择难度。':!s.camp?'先建立寨子。':s.battle||s.scheme||s.event||s.realm?.trek||s.expansion?.run?'先结束当前行动。':!s.team.length?'先安排出阵好汉。':s.team.some(id=>s.heroes[id]?.status!=='owned'||s.affairs?.mission?.hero===id||s.realm?.squad?.team.includes(id))?'出阵好汉尚未归队。':(s.replays?.clears[replayKey(id,tier)]||0)>=10000000?'已达记录上限。':'';}
export function startReplay(s,d,a){requireRule(!replayReason(s,a.id,a.tier,a.challenge),replayReason(s,a.id,a.tier,a.challenge));const m=replayMissions[a.id],choice=Object.values(d.by.stories[a.id].steps).flatMap(x=>x.choices).find(c=>c.battle),context={type:'replay',id:'echo_'+a.id,tier:a.tier,terrain:m.terrain,...(a.challenge?{challenge:a.challenge}:{})};requireRule(choice,'这段主线没有可回顾的战斗。');s.replays??={version:1,clears:{},best:{}};const p=lateMissionPlan(s,context.id,d,a.tier);startBattle(s,d,{enemies:p?.enemies||choice.battle.enemies,scale:p?.scale||m.scale*REPLAY_DIFFICULTIES[a.tier].scale,context});attachTroops(s,0);initializeLateBattle(s,s.battle,d);if(a.challenge==='ambush'){for(const u of s.battle.enemy)u.hp=u.maxHp=Math.round(u.maxHp*1.15);const extra=makeEnemyUnits(d,Array(Math.max(0,5-s.battle.enemy.length)).fill('road_raider'),p?.scale||m.scale);extra.forEach((u,i)=>u.id='reinforcement_'+i);s.battle.enemy.push(...extra);}if(a.challenge==='attrition'){for(const u of s.battle.team)u.hp=Math.round(u.maxHp*.6);for(const u of s.battle.enemy)u.attack=Math.round(u.attack*1.15);}journal(s,'回顾：'+d.by.stories[a.id].title+'。不耗体力、粮草，不带兵、不用药，不发正式主线奖励。');}
export function finishReplay(s,b){const challenge=replayChallengeResult(b);if(challenge?.complete){const key=challengeKey(replayId(b.context.id),b.context.tier,challenge.id),records=s.replays.challenges??={},old=records[key];records[key]={count:(old?.count||0)+1,best:Math.min(old?.best??180000,b.elapsed)};journal(s,'【'+challenge.name+'】达成，战役荣誉已记下；无额外物资奖励。');}else if(challenge)journal(s,'【'+challenge.name+'】未达成：'+challenge.rows.filter(r=>!r.done).map(r=>r.text).join('；')+'。');const key=replayKey(replayId(b.context.id),b.context.tier);if(b.outcome==='victory'){s.replays.clears[key]=(s.replays.clears[key]||0)+1;s.replays.best[key]=Math.min(s.replays.best[key]??180000,b.elapsed);}journal(s,b.outcome==='victory'?'回顾完成，用时 '+(b.elapsed/1000).toFixed(1)+' 秒。成绩已记下，正式剧情保持原选择。':'本次回顾结束，可以调整阵容再试。');s.battle=null;}
