import {ITINERARIES,PREPARATIONS,CONTRACTS,ROUTE_DROPS,defaultPlan,validPlan,contractPassed} from './journey-campaign-data.js?v=0.82.0';
import {requireRule,random,journal} from './utils.js?v=0.82.0';import {gainItem} from './item.js?v=0.82.0';
export function campaignRecord(s){return s.realm.journey.campaign??={version:1,plan:defaultPlan(),contracts:{},clears:0};}
export function campaignPlan(s,a){return {...defaultPlan(),...s.realm?.journey?.campaign?.plan,...Object.fromEntries(['itinerary','preparation','challenge'].filter(k=>a[k]!==undefined).map(k=>[k,a[k]]))};}
export function campaignQuote(s,a){const p=campaignPlan(s,a);if(!validPlan(p))return {reason:'无效的路线、备战或挑战。',plan:p};const m=PREPARATIONS[p.preparation];let reason=m.building&&(!s.camp||s.camp.buildings[m.building]<2)?'这项备战需要对应设施 2 级。':p.challenge!=='none'&&a.tier<2?'挑战契约需要险途或绝险。':'';for(const [id,n]of Object.entries(m.cost)){const have=id==='silver'?s.player.silver:['wood','food'].includes(id)?s.camp?.[id]:s.inventory[id];if(!reason&&(have||0)<n)reason='备战物资不足：'+m.name+'。';}return {reason,plan:p,cost:m.cost};}
export function startCampaign(s,a){const q=campaignQuote(s,a);requireRule(!q.reason,q.reason);for(const [id,n]of Object.entries(q.cost)){if(id==='silver')s.player.silver-=n;else if(['wood','food'].includes(id))s.camp[id]-=n;else s.inventory[id]-=n;}campaignRecord(s);return {version:1,...q.plan,elapsed:0,medicine:0,retired:false,battles:0};}
export function planCampaign(s,a){const p=campaignPlan(s,a);requireRule(validPlan(p),'无效的出行计划。');requireRule(!s.realm?.trek&&!s.expansion?.run,'先完成当前远征。');campaignRecord(s).plan=p;journal(s,'【出行计划】'+ITINERARIES[p.itinerary].name+' · '+PREPARATIONS[p.preparation].name+' · '+CONTRACTS[p.challenge].name+'；确认启程时才扣备战物资。');}
export function campaignBattle(b,j){if(!j.campaign)return;const p=j.campaign;b.journey.campaign={version:1,itinerary:p.itinerary,preparation:p.preparation,challenge:p.challenge};if(p.preparation==='drill')for(const u of b.team)if(u.hp>0)u.rage=Math.min(100,u.rage+10);const scale=CONTRACTS[p.challenge].scale;if(scale!==1)for(const u of b.enemy){u.hp=u.maxHp=Math.round(u.maxHp*scale);u.attack=Math.round(u.attack*scale);u.defense=Math.round(u.defense*scale);}b.log.push('【出行备战】'+PREPARATIONS[p.preparation].text+' '+CONTRACTS[p.challenge].text);}
export function recordCampaignBattle(j,b){if(!j.campaign)return;const p=j.campaign;p.elapsed+=b.elapsed;p.medicine+=b.metrics?.medicineUses||0;p.retired||=b.team.some(u=>u.hp<=0);p.battles++;}
export function finishCampaign(s,d,j,complete){if(!j.campaign)return null;const r=campaignRecord(s),p={...j.campaign,medicine:j.campaign.medicine+(s.realm.trek.packs||0)},drops=ROUTE_DROPS[j.region].map(m=>({id:m.id,count:m.count,won:complete&&random(s)<m.rate}));for(const m of drops)if(m.won)gainItem(s,m.id,m.count,d);const seal=complete&&contractPassed(p)?j.region+':'+p.challenge:null,first=!!seal&&!r.contracts[seal];if(complete)r.clears++;if(seal){const old=r.contracts[seal];r.contracts[seal]={tier:Math.max(old?.tier||0,j.tier),elapsed:old?Math.min(old.elapsed,p.elapsed):p.elapsed};if(first){gainItem(s,'recruit_order',1,d);gainItem(s,'material_choice',2,d);journal(s,'【挑战留名】'+CONTRACTS[p.challenge].name+'首次达标：招贤令 1、材料自选匣 2。此路线本契约不重复发奖。');}}journal(s,'【游历额外掉落】'+(complete?(drops.filter(m=>m.won).map(m=>d.by.items[m.id].name+' ×'+m.count).join('、')||'本次未出现随机物品；必得奖励照常领取。'):'未走通，不判定额外随机奖励。'));return {...p,drops,seal,first};}

