import {tacticsHealing} from './tactics-combat.js?v=0.82.0';
import {validReplayContext} from './replays-data.js?v=0.82.0';
import {validSpecialContext} from './special-dungeons-data.js?v=0.82.0';
import {roleTaken,roleHeal} from './hero-roles.js?v=0.82.0';
import {journeyHealing} from './journey-combat.js?v=0.82.0';import {validateJourneyReport} from './journey-tactics-save.js?v=0.82.0';
import { validEliteContext } from './elites.js?v=0.82.0';
export const METRICS=['damage','healing','taken','controls','interrupts','skills'];
export function newMetrics(team){return {version:1,reason:'ongoing',heroes:Object.fromEntries(team.map(u=>[u.id,Object.fromEntries(METRICS.map(k=>[k,0]))])),dot:0,environment:0,medicine:0,medicineUses:0};}
export function contribution(b,u,key,n=1){const row=u?.side==='team'&&b.metrics?.heroes[u.id];if(row)row[key]+=n;}
export function reportDamage(b,source,target,loss){const n=Math.min(target.hp,loss);roleTaken(b,target,n);if(b.context.type==='lesson'&&b.lesson&&source?.side==='enemy'&&target.side==='team'&&n>0&&b.orders?.stance==='guard')b.lesson.guarded++;contribution(b,source,'damage',n);contribution(b,target,'taken',n);}
export function reportHealing(b,source,n,target){contribution(b,source,'healing',n);tacticsHealing(b,source,target,n,{reportHealing:(b,u,value)=>contribution(b,u,'healing',value)});roleHeal(b,source,target,n);journeyHealing(b,source,n,target);}
export function reportOtherDamage(b,target,loss,kind){const n=Math.min(target.hp,loss);contribution(b,target,'taken',n);if(b.metrics&&((kind==='dot'&&target.side==='enemy')||kind==='environment'))b.metrics[kind]+=n;}
export function saveDebrief(s,b,wounded){s.lastBattle={...(b.tactics?{tacticsReport:{version:1,counts:{...b.tactics.counts}}}:{}),...(b.roles?{roleReport:{version:b.roles.version,counts:{...b.roles.counts}}}:{}),...(b.journey?.combat?{journeyReport:{version:1,region:b.journey.region,kind:b.journey.kind,counts:{...b.journey.combat.counts}}}:{}),at:s.clock,context:{...b.context},outcome:b.outcome,elapsed:b.elapsed||0,troops:b.expedition?.troops||0,wounded:Math.max(0,(s.camp?.wounded||0)-wounded),fallen:b.expedition?.fallen||0,team:b.team.map(({id,hp,maxHp})=>({id,hp,maxHp})),...(b.metrics?{metrics:b.metrics}:{})};}
export function validateDebrief(s,d,check){
 const num=(v,max=1000000000)=>Number.isSafeInteger(v)&&v>=0&&v<=max,obj=v=>v&&typeof v==='object'&&!Array.isArray(v);
 const metrics=(m,ids)=>{check(obj(m)&&m.version===1&&['ongoing','team','enemy','objective','timeout','manual'].includes(m.reason)&&obj(m.heroes),'复盘统计');check(Object.keys(m.heroes).length===ids.length&&ids.every(id=>obj(m.heroes[id])),'复盘人物');for(const row of Object.values(m.heroes))for(const k of METRICS)check(num(row[k]),'贡献数值');check(m.medicineUses===undefined||num(m.medicineUses,1000000),'用药次数');for(const k of ['dot','environment','medicine'])check(num(m[k]),'复盘汇总');};
 if(s.battle?.metrics!==undefined)metrics(s.battle.metrics,s.battle.team.map(u=>u.id));
 const r=s.lastBattle;if(r===undefined)return;
 check(obj(r)&&num(r.at,s.clock)&&['victory','defeat','retreat'].includes(r.outcome)&&num(r.elapsed,180000)&&num(r.troops,1000)&&num(r.wounded,r.troops),'最近战果');if(r.fallen!==undefined)check(num(r.fallen,r.troops)&&r.fallen+r.wounded<=r.troops,'阵亡统计');check(obj(r.context)&&(r.context.type==='replay'?validReplayContext(r.context):r.context.type==='special'?validSpecialContext(r.context):r.context.type==='elite'?validEliteContext(r.context):['story','camp','frontier','dungeon','event','rotation','realm'].includes(r.context.type))&&typeof r.context.id==='string'&&/^[a-z][a-z0-9_]*$/.test(r.context.id),'复盘来源');check(Array.isArray(r.team)&&r.team.length>=1&&r.team.length<=3&&new Set(r.team.map(u=>u.id)).size===r.team.length,'复盘队伍');for(const u of r.team)check(d.by.heroes[u.id]&&num(u.maxHp,1000000)&&u.maxHp>0&&num(u.hp,u.maxHp),'复盘气血');if(r.metrics!==undefined)metrics(r.metrics,r.team.map(u=>u.id));validateJourneyReport(r,check);
}
