import {EXTRA_CHRONICLES} from './talents.js?v=0.82.0';
import { grant } from './item.js?v=0.82.0';
import { count, requireRule, journal } from './utils.js?v=0.82.0';
import { battleTerrain } from './strategy-data.js?v=0.82.0';
const wins=(s,id)=>s.stats['hero_wins_'+id]||0;
export const HERO_CHRONICLES={
 linchong:{title:'枪棒教头',opening:'林冲看过寨中枪架，愿先从站桩、护队教起。',middle:'夜练之后，他请你带新兵走一趟险路，检验阵脚是否稳当。',ending:'枪阵已成，林冲把练兵心得留在寨中。',task:'林冲参与胜利 3 次，并穿戴一件强化 +3 的装备',test:s=>wins(s,'linchong')>=3&&s.equipment.some(e=>e.hero==='linchong'&&e.plus>=3),materials:{iron:6,martial_pages:4}},
 luzhishen:{title:'禅杖护寨',opening:'鲁智深见伤兵归来，先帮医馆挑起了水。',middle:'他愿领队巡护乡路，也请寨中把伤兵安顿妥当。',ending:'乡路渐安，乡人送来布匹，鲁智深笑着让众人收下。',task:'鲁智深参与胜利 3 次，医馆达到 2 级',test:s=>wins(s,'luzhishen')>=3&&s.camp?.buildings.clinic>=2,materials:{cloth:6,mount_feed:4}},
 wuyong:{title:'寨中筹策',opening:'吴用摊开寨务账册，提出先安人心、再议攻守。',middle:'他想用几件来报检验调度，再亲赴阵前察看军情。',ending:'账册添上新章，吴用把成败得失整理成残页。',task:'办妥寨中来报 3 件，吴用参与胜利 1 次',test:s=>(s.affairs?.resolved||0)>=3&&wins(s,'wuyong')>=1,materials:{martial_pages:6,exp_pill:2}},
 huarong:{title:'校场试弓',opening:'花荣在校场立下箭靶，邀同伴轮流试射。',middle:'箭术要与队伍配合，他准备带本部射手出征。',ending:'三番出阵，射手学会了呼应，花荣留下一册心得。',task:'花荣专属部队达到 2 阶，并参与胜利 3 次',test:s=>(s.development?.corps.huarong||1)>=2&&wins(s,'huarong')>=3,materials:{iron:4,martial_pages:6}},
 ruanxiaoqi:{title:'水泊听潮',opening:'阮小七驾舟沿岸探路，邀你留意水势与渡口。',middle:'他要带伙伴在水域实战里学会应对潮汐。',ending:'船桨破开薄雾，水路的呼应已渐渐熟练。',task:'阮小七参与水域胜利 2 次',test:s=>(s.stats.hero_water_wins_ruanxiaoqi||0)>=2,materials:{mount_token:4,mount_feed:6}},
 tanglong:{title:'炉火新篇',opening:'汤隆走进工坊，想把散落的碎铁炼成合用兵器。',middle:'他请你扩建工坊、淬炼兵器，再让他随军检验。',ending:'炉火熄后，新器已成，汤隆将工序刻成图样。',task:'集市达到 3 级，拥有一件 +5 装备，汤隆参与胜利 1 次',test:s=>s.camp?.buildings.market>=3&&s.equipment.some(e=>e.plus>=5)&&wins(s,'tanglong')>=1,materials:{iron:8,scrap_iron:10}}
};
export function chronicleQuote(s,id){const m=HERO_CHRONICLES[id]||EXTRA_CHRONICLES[id],h=s.heroes[id];if(!m)return null;const step=[1,2,3].find(n=>!s.progress.flags['chronicle_'+id+'_'+n]);let reason=!step?'人物行记已完成。':h?.status!=='owned'?'先迎入这位好汉。':!s.camp||s.camp.buildings.hall<2?'聚义厅须达到 2 级。':s.battle||s.scheme||s.event?'先结束当前交战或际遇。':h.level<(step===3?30:10)?'人物须达 '+(step===3?30:10)+' 级。':step===2&&!m.test(s)?m.task:step===3&&((h.quality||0)<1||wins(s,id)<8)?'须达到灵品，且本人参与胜利 8 次。':'';return {step,reason,model:m};}
export function claimChronicle(s,d,a){const q=chronicleQuote(s,a.id);requireRule(q&&!q.reason,q?.reason||'此人物行记尚未开放。');requireRule(q.step===a.step,'这段行记已结算，请重新查看。');requireRule(['practice','supplies'].includes(a.choice),'请选择行记酬谢。');const items=a.choice==='practice'?{[a.id+'_manual']:q.step,exp_pill:q.step}:q.step===3?{[a.id+'_token']:3,spirit_essence:3}:q.model.materials;s.progress.flags['chronicle_'+a.id+'_'+q.step]=true;s.progress.flags['chronicle_'+a.id+'_'+q.step+'_'+a.choice]=true;grant(s,{items},d);journal(s,'【人物行记】'+d.by.heroes[a.id].name+' · '+[q.model.opening,q.model.middle,q.model.ending][q.step-1]+' 酬谢已选：'+(a.choice==='practice'?'个人修习':'寨中物资')+'。');}
export function recordHeroWins(s,b){if(b.guest)return;for(const u of b.team){count(s,'hero_wins_'+u.id);if(battleTerrain(b)==='water')count(s,'hero_water_wins_'+u.id);}}
export function chroniclePanel(s,d,h,btn){const q=chronicleQuote(s,h.id);if(!q)return '';const m=q.model;return '<details class="fold-section" data-fold="chronicle-'+h.id+'"><summary>人物行记 · '+m.title+' · '+[1,2,3].filter(n=>s.progress.flags['chronicle_'+h.id+'_'+n]).length+' / 3</summary><p class="note">本作支线。参与胜利从本版开始记录：'+wins(s,h.id)+' 次；已完成的等级、设施、装备条件直接计入。</p>'+[m.opening,m.middle,m.ending].map((text,i)=>'<p><b>第 '+(i+1)+' 段'+(s.progress.flags['chronicle_'+h.id+'_'+(i+1)]?' · 已记':'')+'</b> '+text+'</p><p class="note">'+["聚义厅 2 级、本人 10 级",m.task,'本人 30 级、灵品、参与胜利 8 次'][i]+'</p>').join('')+(q.step?'<p class="note">'+(q.reason||'本段条件已满足，可任选一份酬谢。')+'</p><p class="note">个人修习：专属招式书 '+q.step+'、经验丹 '+q.step+'；寨中物资：'+Object.entries(q.step===3?{[h.id+'_token']:3,spirit_essence:3}:m.materials).map(([id,n])=>d.by.items[id].name+' '+n).join('、')+'。每段只能选一次。</p>'+btn('选择个人修习',{type:'heroChronicleClaim',id:h.id,step:q.step,choice:'practice'},'secondary',!!q.reason)+btn('选择寨中物资',{type:'heroChronicleClaim',id:h.id,step:q.step,choice:'supplies'},'secondary',!!q.reason):'<p>三段行记已完成，酬谢不可重复领取。</p>')+'</details>';}
