import {WORKSHOP_RECIPES} from './supplies-data.js?v=0.82.0';
import {staminaCap} from './logistics.js?v=0.82.0';
import {expansion} from './expansion-state.js?v=0.82.0';
import {requireRule,count,journal,hasOwn} from './utils.js?v=0.82.0';
import {pay,grant} from './item.js?v=0.82.0';
import {rotationCalendar} from './rotations.js?v=0.82.0';
export const RECIPES={...WORKSHOP_RECIPES,mount_feed:{name:'草料调配',building:'farm',silver:20,items:{horse_feed:3,herb:1},limit:2},ration:{name:'膳房干粮',building:'farm',food:35,silver:20,items:{grain:2},limit:2},camp_pack:{name:'野营药包',building:'clinic',silver:35,items:{herb:5,cloth:2},limit:2},medical_crate:{name:'军医药箱',building:'clinic',silver:50,items:{herb:8,tiger_bone:1,cloth:2},limit:2},smoke_pack:{name:'护行烟幕',building:'market',silver:45,items:{herb:3,tiger_skin:1},limit:1}};
export const BOX_OPTIONS={iron:5,cloth:5,herb:8,martial_pages:3};
export const ordinaryUsed=s=>(s.daily.counters.wine||0)*10+(s.daily.counters.ration||0)*20;
export function staminaQuote(s,id){const cap=staminaCap(s),amount=id==='wine'?10:id==='ration'?20:id==='vital_pill'?Math.ceil(cap*.3):0;let reason=!amount?'不是体力补给':!(s.inventory[id]>0)?'行囊中没有此物':s.battle||s.scheme||s.event||s.realm?.trek||s.expansion?.run?'先结束交战或远征':s.player.stamina>=cap?'体力已满':id==='wine'&&(s.daily.counters.wine||0)>=2?'今日已饮两次村酒':id==='vital_pill'&&s.daily.counters.vital_pill?'今日已服用养元丹':id!=='vital_pill'&&ordinaryUsed(s)+amount>60?'今日普通补给额度不足':'';return {reason,amount,actual:Math.min(amount,cap-s.player.stamina),before:s.player.stamina,after:Math.min(cap,s.player.stamina+amount),cap};}
export function useStamina(s,id){const q=staminaQuote(s,id);requireRule(!q.reason,q.reason);if(id!=='wine')expansion(s);s.inventory[id]--;s.player.stamina=q.after;if(q.after===q.cap)s.lastRegen=s.clock;count(s,id);journal(s,'【体力补给】恢复 '+q.actual+' 点体力，现为 '+q.after+' / '+q.cap+'。');}
export function provisionAction(s,d,a){const x=expansion(s),id=a.id;if(a.type==='provisionUse'){requireRule(!s.realm?.trek||id==='camp_pack','远征途中只能使用野营药包。');if(['ration','vital_pill','wine'].includes(id)){useStamina(s,id);return;}requireRule(s.inventory[id]>0,'缺少道具。');if(id==='camp_pack'){const t=s.realm?.trek;requireRule(t&&Object.values(t.hp).some(v=>v>0&&v<10000),'远征节点间有未退阵且受伤的好汉才可使用。');requireRule((t.packs||0)<2,'本次远征已使用两包。');for(const h of t.team)if(t.hp[h]>0)t.hp[h]=Math.min(10000,t.hp[h]+2000);t.packs=(t.packs||0)+1;}else if(id==='medical_crate'){requireRule(s.camp?.buildings.clinic>=2&&s.camp.wounded>0,'医馆 2 级且有伤兵才可用。');const n=Math.min(30,s.camp.wounded);requireRule(s.camp.food>=n,'治疗还需要粮草 '+n+'。');s.camp.food-=n;s.camp.wounded-=n;s.camp.troops+=n;}else if(id==='material_choice'){requireRule(hasOwn(BOX_OPTIONS,a.choice),'请选择箱中一份材料。');grant(s,{items:{[a.choice]:BOX_OPTIONS[a.choice]}},d);}else throw Error('此物不能直接使用。');s.inventory[id]--;journal(s,'【军需使用】'+d.by.items[id].name+'已使用。');return;}
 if(a.type==='provisionUnlock'){const r=RECIPES[id];requireRule(r&&s.camp?.buildings[r.building]>=2,'配方需要对应设施 2 级。');requireRule(!x.recipes.includes(id),'已经学会此配方。');pay(s,{silver:60});x.recipes.push(id);journal(s,'【配方发现】学会'+r.name+'，可在行囊加工。');return;}
 if(a.type==='provisionCraft'){const r=RECIPES[id];requireRule(r&&x.recipes.includes(id)&&s.camp?.buildings[r.building]>=2,'先学会配方并修好对应设施。');requireRule((s.inventory[id]||0)<10000000,'此材料已达存储上限。');requireRule((s.daily.counters['craft_'+id]||0)<r.limit,'今日此配方加工次数已用完。');requireRule((s.camp?.food||0)>=(r.food||0),'粮草不足。');pay(s,{silver:r.silver,items:r.items});s.camp.food-=r.food||0;grant(s,{items:{[id]:1}},d);count(s,'craft_'+id);journal(s,'【军需加工】获得'+d.by.items[id].name+'一份。');return;}
 if(a.type==='provisionWeekly'){const p=rotationCalendar(s.clock).period;requireRule(s.campaign?.weekly[p]?.tier>=2,'本期周本达到 2 层后领取。');const f='kit_week_'+p.replaceAll('-','_');requireRule(!s.progress.flags[f],'本期已经领取。');s.progress.flags[f]=true;grant(s,{items:{vital_pill:1,material_choice:1}},d);return;}
 if(a.type==='provisionMilestone'){const c=d.chapters.find(v=>v.id===id);requireRule(c&&s.progress.flags[c.completeFlag],'先完成这一卷。');const f='kit_chapter_'+id;requireRule(!s.progress.flags[f],'本卷补给已经领取。');s.progress.flags[f]=true;grant(s,{items:{vital_pill:1,material_choice:1}},d);return;}throw Error('未知补给操作。');}
