import {MINE_COMPANION_TASKS} from './mine-companion-data.js?v=0.82.0';
import {EXPEDITIONS} from './realm-data.js?v=0.82.0';import {startBattle,advanceBattle} from './battle.js?v=0.82.0';import {attachTroops,TACTICS} from './camp.js?v=0.82.0';import {heroCommand} from './logistics.js?v=0.82.0';import {casualtyQuote} from './fieldcraft.js?v=0.82.0';import {affairReward} from './affairs.js?v=0.82.0';import {gainExp} from './hero.js?v=0.82.0';import {clone,requireRule,hasOwn,count,journal} from './utils.js?v=0.82.0';
export const reservedTroops=s=>s.realm?.squad?.troops||0;
export const squadAway=(s,id)=>!!s.realm?.squad?.team.includes(id);
export function squadAvailable(s,id){return s.idleDispatch?.mission?.hero!==id&&s.heroes[id]?.status==='owned'&&!s.team.includes(id)&&s.affairs?.mission?.hero!==id&&!s.progress.flags['camp_steward_'+id]&&!Object.values(s.frontier?.stations||{}).some(p=>p.worker==='hero:'+id)&&!Object.values(s.frontier?.posts||{}).some(p=>p.guard===id)&&!squadAway(s,id);}
export function assignmentGuard(s,d,a){
 // Goals and mine errands do not change a dispatched hero or their loadout.
 if(a.type==='goalSet'||a.type==='regionDo'&&Object.hasOwn(MINE_COMPANION_TASKS,a.id))return;
 const team=[...(s.realm?.squad?.team||[]),...(s.idleDispatch?.mission?[s.idleDispatch.mission.hero]:[])];if(!team.length)return;const touched=[a.mentor,a.student,a.from,a.to,a.hero,a.worker?.replace('hero:',''),...(a.ids||[]),...(a.type==='presetLoad'?(s.development?.presets[a.id||a.slot]?.team||[]):[])];if(a.id){touched.push(a.id);const e=s.equipment.find(e=>e.uid===a.id);if(e?.hero)touched.push(e.hero);for(const id of team)if(typeof a.id==='string'&&a.id.startsWith(id+'_'))touched.push(id);}requireRule(!touched.some(id=>team.includes(id)),(s.idleDispatch?.mission&&touched.includes(s.idleDispatch.mission.hero)?'这位好汉仍在采集派遣':'这位好汉仍在分队外派')+'，请接回后再调整阵容、装备或培养。');}
export function squadQuote(s,d,a){try{const m=EXPEDITIONS[a.id];requireRule(s.realm&&s.camp.buildings.hall>=2,'开启山河经营且聚义厅 2 级后可派第二支队伍。');requireRule(!s.realm.squad,'第二支队伍尚未归营。');requireRule(m,'未知外派路线。');requireRule(!s.daily.counters.squad_dispatch,'分队每日出发一次，次日可继续派遣。');requireRule(Array.isArray(a.team)&&a.team.length>0&&a.team.length<=3&&new Set(a.team).size===a.team.length&&a.team.every(id=>squadAvailable(s,id)),'分队须安排 1—3 名未在主队、任职或外派中的入寨好汉。');requireRule(Number.isInteger(a.troops)&&a.troops>=0&&a.troops<=300&&a.troops<=s.camp.troops&&a.troops<=a.team.reduce((n,id)=>n+heroCommand(s,id),0),'分队兵力须为 0—300，且不超过在营人数和统兵上限。');const food=10+Math.ceil(a.troops/2);requireRule(s.player.stamina>=10&&s.camp.food>=food,'需要体力 10 和粮草 '+food+'。');const sim=clone(s);sim.team=[...a.team];sim.camp.mode=a.troops?'army':'solo';sim.camp.troops=a.troops;sim.realm.armyXp=Math.floor((s.realm.armyXp||0)*a.troops/Math.max(1,s.camp.troops+s.camp.wounded));sim.camp.wounded=0;sim.realm.squad=null;if(sim.expansion)sim.expansion.smoke=false;sim.battleSkillMode='auto';startBattle(sim,d,{enemies:m.enemies,scale:m.scale,context:{type:'realm',kind:'squad',id:a.id,terrain:'land'}});attachTroops(sim,a.troops);for(let i=0;i<180&&!sim.battle.outcome;i++)advanceBattle(sim,d,1000);const b=sim.battle,q=casualtyQuote(b,TACTICS[sim.camp.tactic].loss);return {reason:'',food,rng:sim.rng,mission:{id:a.id,team:[...a.team],troops:a.troops,readyAt:s.clock+m.minutes*60000,training:s.realm.branches.barracks==='veterans'?1.25:1,xp:Math.floor((s.realm.armyXp||0)*a.troops/Math.max(1,s.camp.troops+s.camp.wounded)),outcome:b.outcome,fallen:q.fallen,wounded:q.wounded,elapsed:b.elapsed}};}catch(e){return {reason:e.message};}}
export function squadAction(s,d,a){if(a.type==='squadSend'){const q=squadQuote(s,d,a);requireRule(!q.reason,q.reason);s.player.stamina-=10;s.camp.food-=q.food;s.camp.troops-=q.mission.troops;s.realm.armyXp-=q.mission.xp;s.realm.squad=q.mission;s.rng=q.rng;count(s,'squad_dispatch');journal(s,'【分队出发】'+q.mission.team.map(id=>d.by.heroes[id].name).join('、')+'率 '+q.mission.troops+' 人前去'+EXPEDITIONS[a.id].name+'。');return;}const m=s.realm?.squad;requireRule(m,'没有在外分队。');requireRule(a.type==='squadCollect'&&s.clock>=m.readyAt,'分队尚未抵达归程时间。');s.camp.troops+=m.troops-m.fallen-m.wounded;s.camp.wounded+=m.wounded;s.camp.fallen=(s.camp.fallen||0)+m.fallen;s.realm.armyXp=Math.min((s.camp.troops+s.camp.wounded)*200,s.realm.armyXp+Math.floor(m.xp*(m.troops-m.fallen)/Math.max(1,m.troops))+Math.floor((m.troops-m.fallen)*(m.outcome==='victory'?20:5)*(m.training||1)));if(m.outcome==='victory'){affairReward(s,EXPEDITIONS[m.id].reward,d);for(const id of m.team)gainExp(s,id,200,d);count(s,'squad_wins');}journal(s,'【分队归来】'+EXPEDITIONS[m.id].name+' · '+(m.outcome==='victory'?'办妥委托':'未能完成')+'，伤兵 '+m.wounded+'、阵亡 '+m.fallen+'；英雄均已回寨。');s.realm.squad=null;}
export function validateSquad(s,check){const m=s.realm?.squad;if(m===null||m===undefined)return;const num=(v,max)=>Number.isSafeInteger(v)&&v>=0&&v<=max;check(m&&hasOwn(EXPEDITIONS,m.id)&&Array.isArray(m.team)&&m.team.length>=1&&m.team.length<=3&&new Set(m.team).size===m.team.length&&m.team.every(id=>s.heroes[id]?.status==='owned'&&!s.team.includes(id)&&s.affairs?.mission?.hero!==id&&!s.progress.flags['camp_steward_'+id]&&!Object.values(s.frontier?.stations||{}).some(p=>p.worker==='hero:'+id)&&!Object.values(s.frontier?.posts||{}).some(p=>p.guard===id)),'分队人员互斥');check((m.training===undefined||[1,1.25].includes(m.training))&&num(m.troops,300)&&num(m.fallen,m.troops)&&num(m.wounded,m.troops-m.fallen)&&num(m.xp,m.troops*200)&&num(m.readyAt,s.clock+15*60000)&&num(m.elapsed,180000)&&['victory','defeat','retreat'].includes(m.outcome),'分队行程');}
