import {addStatus} from './battle.js?v=0.82.0';
import {veteranBonus} from './veterans.js?v=0.82.0';
import {TALENTS} from './talents.js?v=0.82.0';
export function initializeRealmBattle(s,b){if(!s.realm||b.guest||b.realm)return;b.realm={version:1,medical:s.realm.branches.clinic==='field'?.9:1,relic:s.realm.equipped,veteran:veteranBonus(s),paths:Object.fromEntries(b.team.filter(u=>s.realm.paths?.[u.id]).map(u=>[u.id,s.realm.paths[u.id]])),qualities:Object.fromEntries(b.team.map(u=>[u.id,s.heroes[u.id].quality||0]))};for(const u of b.team){if(b.context.type==='realm'&&b.context.kind==='trek'&&s.realm.trek?.hp[u.id]===0)continue;if(b.realm.relic==='banner'&&(b.depth?.terrain==='water'||b.context.kind==='escort'||['convoy','stable','escort'].includes(b.context.id)))addStatus(u,{id:'guard',value:.08,turns:6},0);if(b.realm.relic==='drum'){u.rage=Math.min(100,u.rage+8);u.defense=Math.round(u.defense*.96);}if(u.corps?.troops){u.attack=Math.round(u.attack*(1+b.realm.veteran));u.defense=Math.round(u.defense*(1+b.realm.veteran));}const m=TALENTS[u.id];if(m?.kind==='rally')for(const ally of b.team)ally.rage=Math.min(100,ally.rage+m.value);if(m?.kind==='guard')u.defense=Math.round(u.defense*(1+m.value));if(m?.kind==='haste')u.nextAttackAt=Math.max(300,u.nextAttackAt-m.value);const q=b.realm.qualities[u.id],path=b.realm.paths[u.id];if(path==='assault')u.defense=Math.round(u.defense*.96);if(path==='guard'){u.defense=Math.round(u.defense*(q===2?1.14:1.08));}if(m)b.log.push('【天罡本领】'+u.name+' · '+m.name+'：'+m.text);}}
