import {RELICS} from './realm-data.js?v=0.82.0';import {requireRule,hasOwn,journal} from './utils.js?v=0.82.0';import {affairReward} from './affairs.js?v=0.82.0';export const relicEarned=(s,id)=>id==='banner'?Math.floor((s.stats.realm_win_commission||0)/3):id==='drum'?Math.floor((s.stats.realm_win_raid||0)/5):s.stats.trek_wins||0;
export function relicAction(s,d,a){requireRule(s.realm&&hasOwn(RELICS,a.id),'先开启山河经营并选择有效战利品。');if(a.type==='relicEquip'){requireRule(s.realm.relics.includes(a.id),'先取得这件战利品。');s.realm.equipped=s.realm.equipped===a.id?null:a.id;journal(s,'【军中藏品】'+(s.realm.equipped?'携带'+RELICS[a.id].name:'已卸下藏品')+'，后续新战局生效。');return;}requireRule(a.type==='relicClaim','无效藏品指令。');s.realm.relicClaims??={};const earned=relicEarned(s,a.id),claimed=s.realm.relicClaims[a.id]||0;requireRule(earned>claimed,'尚未完成下一份取得条件，或已经领取。');s.realm.relicClaims[a.id]=claimed+1;if(s.realm.relics.includes(a.id)){affairReward(s,{items:{scrap_iron:3,martial_pages:2}},d);journal(s,'【重复藏品】'+RELICS[a.id].name+'转为碎铁 3、武学残页 2。');}else{s.realm.relics.push(a.id);journal(s,'【获得藏品】'+RELICS[a.id].name+'。可在山河页面选择携带，全军一次仅携一件。');}}
export function relicsPanel(s,btn){return '<section class="realm-section" id="realm-relic"><h2>军中藏品 · 改变打法的战利品</h2><p>全军只能携带一件。固定条件取得，不需要抽取；重复取得自动转为碎铁 3、武学残页 2。</p><div class="realm-grid">'+Object.entries(RELICS).map(([id,v])=>'<article class="realm-card"><h3>'+v.name+(s.realm.relics.includes(id)?' · 已得':' · 未得')+'</h3><p>'+v.text+'</p><p class="note">'+v.source+'。每再次满足相同次数，可领一件重复藏品。</p>'+btn('领取已达成的藏品',{type:'relicClaim',id},'primary',relicEarned(s,id)<=(s.realm.relicClaims?.[id]||0))+btn(s.realm.equipped===id?'已携带 · 点击卸下':'携带此件',{type:'relicEquip',id},'secondary',!s.realm.relics.includes(id))+'</article>').join('')+'</div></section>';}
