import {GRAIN_ROUTES,GRAIN_INVESTMENTS,grainRoute} from './grain-road-data.js?v=0.82.0';
export const hasGrainRoad=s=>s.grainRoad!==undefined;
export function validateGrainRoad(s,check){const x=s.grainRoad,b=s.battle,isBattle=b?.context.type==='camp'&&grainRoute(b.context.id);if(x===undefined){check(!isBattle,'粮路战役缺少记录');return;}const obj=v=>v&&typeof v==='object'&&!Array.isArray(v),num=(v,max=10000000)=>Number.isSafeInteger(v)&&v>=0&&v<=max;check(obj(x)&&Object.keys(x).sort().join(',')==='attempts,investment,last,lastAt,route,scout,version,won'&&x.version===1&&!!s.camp,'粮路记录');check(x.route===null||Object.hasOwn(GRAIN_ROUTES,x.route),'粮路方案');check(x.scout===null||s.heroes[x.scout]?.status==='owned','探路好汉');check(typeof x.won==='boolean'&&num(x.attempts)&&num(x.lastAt,s.clock)&&(x.investment===null||Object.hasOwn(GRAIN_INVESTMENTS,x.investment)),'粮路进度');check(x.won?x.attempts>0&&x.route!==null&&x.last?.outcome==='victory':x.investment===null&&x.lastAt===0,'粮路结局');check((x.route==='scout'||x.last?.route==='scout')?!!x.scout:true,'探路前置');check(x.attempts===0?x.route===null&&x.last===null:x.route!==null,'粮路尝试');if(isBattle)check(!x.won&&x.attempts>0&&x.route===isBattle&&b.context.terrain===GRAIN_ROUTES[x.route].terrain,'粮路在途状态');
 if(x.last!==null){const r=x.last;check(obj(r)&&Object.keys(r).sort().join(',')==='cargo,fallen,outcome,route,troops,wounded'&&Object.hasOwn(GRAIN_ROUTES,r.route)&&['victory','defeat','retreat'].includes(r.outcome)&&num(r.cargo,100)&&num(r.troops,1000)&&num(r.wounded,r.troops)&&num(r.fallen,r.troops)&&r.wounded+r.fallen<=r.troops,'粮路战果');check((r.outcome==='victory')===x.won&&(!x.won||r.route===x.route),'粮路结算方案');}
}
export function grainRoadPreserved(a,b){const x=a.grainRoad,y=b.grainRoad;return !x||!!y&&y.attempts>=x.attempts&&(!x.scout||y.scout===x.scout)&&(!x.won||y.won&&y.route===x.route&&y.lastAt>=x.lastAt)&&(!x.investment||y.investment===x.investment);}
